// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Health The instance and what it holds
	// (GET /health)
	Health(ctx context.Context, request HealthRequestObject) (HealthResponseObject, error)
	// ForgetKey Forget the engine's share, its nonces and sessions (the key was revoked)
	// (DELETE /keys/{keyId})
	ForgetKey(ctx context.Context, request ForgetKeyRequestObject) (ForgetKeyResponseObject, error)
	// GetKey What the service holds for the key
	// (GET /keys/{keyId})
	GetKey(ctx context.Context, request GetKeyRequestObject) (GetKeyResponseObject, error)
	// ImportKey Store a dealt engine share for the key
	// (PUT /keys/{keyId})
	ImportKey(ctx context.Context, request ImportKeyRequestObject) (ImportKeyResponseObject, error)
	// IssueCommitments Make single-use FROST commitments with the engine's share
	// (POST /keys/{keyId}/commitments)
	IssueCommitments(ctx context.Context, request IssueCommitmentsRequestObject) (IssueCommitmentsResponseObject, error)
	// Finish Finish one signature from a presigned slot and the agent's last message
	// (POST /keys/{keyId}/finish)
	Finish(ctx context.Context, request FinishRequestObject) (FinishResponseObject, error)
	// FrostSign The engine's share of a FROST signature, aggregated with the agent's into the Ed25519 signature
	// (POST /keys/{keyId}/frost-sign)
	FrostSign(ctx context.Context, request FrostSignRequestObject) (FrostSignResponseObject, error)
	// KeygenStep One step of two-party key generation, the service as party 1
	// (POST /keys/{keyId}/keygen)
	KeygenStep(ctx context.Context, request KeygenStepRequestObject) (KeygenStepResponseObject, error)
	// PresignStep One step of presigning a batch of nonces, the service as party 1
	// (POST /keys/{keyId}/presign)
	PresignStep(ctx context.Context, request PresignStepRequestObject) (PresignStepResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

